mapper.select:
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT /* BmsXraySendMapper.selectXraySendList : XRAY판독결과,반출승인 재전송리스트 조회 */ BL_NO ,hms.PACKING_NO AS REFERENCE_NO ,SEQ ,SEND_STATUS ,hms.REGISTER_DATE_TIME ,hms.UPDATE_DATE_TIME ,'X_RAY_SCAN' AS SEND_TYPE ,'XRAY판독결과HMS전송' AS SEND_TYPE_NAME FROM TB_BMS_XRAY_RESULT_TEMP hms LEFT JOIN TB_ECM_OD od ON hms.OD_JOB_NO = od.OD_JOB_NO WHERE XRAY_DATE != '' AND SEND_STATUS = 'F'
AND hms.BL_NO IN (#{item})
AND hms.BL_NO = #{srchHblNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
UNION ALL SELECT BL_NO ,hms.OUT_APPROVAL_NO AS REFERENCE_NO ,SEQ ,SEND_STATUS ,hms.REGISTER_DATE_TIME ,hms.UPDATE_DATE_TIME ,'RELEASE_APPROVAL' AS SEND_TYPE ,'반출승인내역HMS전송' AS SEND_TYPE_NAME FROM TB_BMS_OUT_PLAN_TEMP hms WHERE SEND_STATUS = 'F'
AND hms.BL_NO IN (#{item})
AND hms.BL_NO = #{srchHblNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
/* BmsXraySendMapper.selectXraySendTypeList : XRAY판독결과,반출승인 재전송리스트 조회 */
SELECT BL_NO ,hms.PACKING_NO AS REFERENCE_NO ,SEQ ,SEND_STATUS ,hms.REGISTER_DATE_TIME ,hms.UPDATE_DATE_TIME ,'X_RAY_SCAN' AS SEND_TYPE ,'XRAY판독결과HMS전송' AS SEND_TYPE_NAME FROM TB_BMS_XRAY_RESULT_TEMP hms LEFT JOIN TB_ECM_OD od ON hms.OD_JOB_NO = od.OD_JOB_NO WHERE XRAY_DATE != '' AND SEND_STATUS = 'F'
SELECT BL_NO ,hms.OUT_APPROVAL_NO AS REFERENCE_NO ,SEQ ,SEND_STATUS ,hms.REGISTER_DATE_TIME ,hms.UPDATE_DATE_TIME ,'RELEASE_APPROVAL' AS SEND_TYPE ,'반출승인내역HMS전송' AS SEND_TYPE_NAME FROM TB_BMS_OUT_PLAN_TEMP hms WHERE SEND_STATUS = 'F'
AND hms.BL_NO IN (#{item})
AND hms.BL_NO = #{srchHblNo}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
